/**
 * Authentication + access control.
 *
 *  - Admin   : username + password (password hashed with scrypt, changeable
 *              from the admin panel at any time)
 *  - Visitor : access codes generated by the admin. Codes can be created,
 *              renamed, rotated, disabled, expired or deleted at any time.
 */
import crypto from 'node:crypto';
import {
  hashPassword,
  verifyPassword,
  randomCode,
  randomId,
  signToken,
  verifyToken,
  parseCookies,
} from './util.js';

const COOKIE_NAME = 'nxs_session';
const DEFAULT_SETTINGS = {
  requireLogin: true,
  allowCustomStreams: true,
  siteName: '',
  tagline: '',
  scanRate: 5,
  hideOffline: true,
};

export class Auth {
  constructor({ store, config, log = console }) {
    this.store = store;
    this.config = config;
    this.log = log;
    this.secret = config.sessionSecret || '';
    this.admin = { user: config.adminUser, hash: '' };
    this.settings = { ...DEFAULT_SETTINGS };
    this.codes = [];
  }

  async init() {
    // ---- session secret -------------------------------------------------
    if (!this.secret) {
      this.secret = (await this.store.get('auth:secret')) || crypto.randomBytes(32).toString('hex');
      await this.store.set('auth:secret', this.secret);
    }

    // ---- admin account --------------------------------------------------
    const storedAdmin = await this.store.get('auth:admin');
    if (storedAdmin?.hash) {
      this.admin = storedAdmin;
    } else if (this.config.adminPassword) {
      this.admin = {
        user: this.config.adminUser || 'admin',
        hash: hashPassword(this.config.adminPassword),
        createdAt: Date.now(),
      };
      await this.store.set('auth:admin', this.admin);
      this.log.log(`[auth] admin "${this.admin.user}" initialised from ADMIN_PASSWORD`);
    } else {
      const generated = randomCode(12);
      this.admin = {
        user: this.config.adminUser || 'admin',
        hash: hashPassword(generated),
        createdAt: Date.now(),
        generated: true,
      };
      await this.store.set('auth:admin', this.admin);
      this.log.log('');
      this.log.log('  +----------------------------------------------------------+');
      this.log.log('  |  FIRST RUN - ADMIN CREDENTIALS (change them immediately)   |');
      this.log.log(`  |  user: ${this.admin.user.padEnd(48)}|`);
      this.log.log(`  |  pass: ${generated.padEnd(48)}|`);
      this.log.log('  +----------------------------------------------------------+');
      this.log.log('');
    }

    // ---- settings + codes ----------------------------------------------
    const storedSettings = (await this.store.get('settings')) || {};
    this.settings = { ...DEFAULT_SETTINGS, ...storedSettings };
    if (this.config.siteName) this.settings.siteName = this.config.siteName;
    if (this.config.siteTagline) this.settings.tagline = this.config.siteTagline;
    if (this.config.requireLogin !== undefined && !storedSettings.requireLogin) {
      // env only applies on first boot
      this.settings.requireLogin = storedSettings.requireLogin ?? this.config.requireLogin;
    }
    if (this.config.allowCustomStreams !== undefined && storedSettings.allowCustomStreams === undefined) {
      this.settings.allowCustomStreams = this.config.allowCustomStreams;
    }
    await this.store.set('settings', this.settings);

    this.codes = (await this.store.get('codes')) || [];
    if (!Array.isArray(this.codes)) this.codes = [];
  }

  // --------------------------------------------------------------- settings
  async updateSettings(patch = {}) {
    const next = { ...this.settings };
    if (typeof patch.requireLogin === 'boolean') next.requireLogin = patch.requireLogin;
    if (typeof patch.allowCustomStreams === 'boolean') next.allowCustomStreams = patch.allowCustomStreams;
    if (typeof patch.hideOffline === 'boolean') next.hideOffline = patch.hideOffline;
    if (typeof patch.siteName === 'string' && patch.siteName.trim()) {
      next.siteName = patch.siteName.trim().slice(0, 60);
    }
    if (typeof patch.tagline === 'string') next.tagline = patch.tagline.slice(0, 120);
    if (patch.scanRate !== undefined) {
      const rate = Number(patch.scanRate);
      if (Number.isFinite(rate)) next.scanRate = Math.min(Math.max(rate, 1), 40);
    }
    this.settings = next;
    await this.store.set('settings', next);
    return next;
  }

  // ------------------------------------------------------------------ codes
  async persistCodes() {
    await this.store.set('codes', this.codes);
  }

  async createCode(input = {}) {
    const label = String(input.label || 'Guest').trim().slice(0, 40) || 'Guest';
    const code = (input.code ? String(input.code).trim().toUpperCase() : randomCode(8)).slice(0, 24);
    if (this.codes.some((c) => c.code === code)) {
      const err = new Error('code already exists');
      err.status = 409;
      throw err;
    }
    const entry = {
      id: randomId(6),
      code,
      label,
      note: String(input.note || '').slice(0, 160),
      enabled: input.enabled !== false,
      expiresAt: input.expiresAt ? Number(input.expiresAt) : null,
      maxUses: input.maxUses ? Number(input.maxUses) : null,
      uses: 0,
      createdAt: Date.now(),
    };
    this.codes.push(entry);
    await this.persistCodes();
    return entry;
  }

  async updateCode(id, patch = {}) {
    const entry = this.codes.find((c) => c.id === id);
    if (!entry) {
      const err = new Error('code not found');
      err.status = 404;
      throw err;
    }
    if (typeof patch.label === 'string') entry.label = patch.label.trim().slice(0, 40) || entry.label;
    if (typeof patch.note === 'string') entry.note = patch.note.slice(0, 160);
    if (typeof patch.enabled === 'boolean') entry.enabled = patch.enabled;
    if (patch.expiresAt === null || patch.expiresAt === '') entry.expiresAt = null;
    else if (patch.expiresAt !== undefined) entry.expiresAt = Number(patch.expiresAt);
    if (patch.maxUses === null || patch.maxUses === '') entry.maxUses = null;
    else if (patch.maxUses !== undefined) entry.maxUses = Number(patch.maxUses);
    if (patch.code) {
      const code = String(patch.code).trim().toUpperCase().slice(0, 24);
      if (code && !this.codes.some((c) => c.code === code && c.id !== id)) {
        const err = new Error('code already exists');
        err.status = 409;
        throw err;
      }
      if (code) entry.code = code;
    }
    await this.persistCodes();
    return entry;
  }

  async rotateCode(id) {
    const entry = this.codes.find((c) => c.id === id);
    if (!entry) {
      const err = new Error('code not found');
      err.status = 404;
      throw err;
    }
    let code = randomCode(8);
    while (this.codes.some((c) => c.code === code && c.id !== id)) code = randomCode(8);
    entry.code = code;
    entry.uses = 0;
    entry.rotatedAt = Date.now();
    await this.persistCodes();
    return entry;
  }

  async deleteCode(id) {
    const before = this.codes.length;
    this.codes = this.codes.filter((c) => c.id !== id);
    if (this.codes.length === before) {
      const err = new Error('code not found');
      err.status = 404;
      throw err;
    }
    await this.persistCodes();
    return true;
  }

  codeIsValid(entry) {
    if (!entry || !entry.enabled) return false;
    if (entry.expiresAt && entry.expiresAt < Date.now()) return false;
    if (entry.maxUses && entry.uses >= entry.maxUses) return false;
    return true;
  }

  // ------------------------------------------------------------------ login
  async loginAdmin(username, password) {
    const user = String(username || '').trim();
    if (!user || !password) return { ok: false, reason: 'missing credentials' };
    if (user.toLowerCase() !== String(this.admin.user).toLowerCase()) {
      await hashPassword(password); // constant-ish work to avoid user enumeration
      return { ok: false, reason: 'invalid credentials' };
    }
    if (!verifyPassword(password, this.admin.hash)) return { ok: false, reason: 'invalid credentials' };
    return { ok: true, role: 'admin', sub: this.admin.user };
  }

  async loginVisitor(code) {
    const value = String(code || '').trim().toUpperCase();
    if (!value) return { ok: false, reason: 'missing code' };
    const entry = this.codes.find((c) => c.code.toUpperCase() === value);
    if (!entry) return { ok: false, reason: 'invalid code' };
    if (!this.codeIsValid(entry)) return { ok: false, reason: 'code expired or disabled' };
    entry.uses = (entry.uses || 0) + 1;
    entry.lastUsedAt = Date.now();
    await this.persistCodes();
    return { ok: true, role: 'visitor', sub: entry.id, label: entry.label };
  }

  async changeAdminPassword(currentPassword, newPassword, currentUser) {
    if (String(currentUser || '').trim().toLowerCase() !== String(this.admin.user).toLowerCase()) {
      return { ok: false, reason: 'invalid credentials' };
    }
    if (!verifyPassword(currentPassword, this.admin.hash)) return { ok: false, reason: 'invalid credentials' };
    if (!newPassword || String(newPassword).length < 6) {
      return { ok: false, reason: 'password too short (min 6)' };
    }
    this.admin = { ...this.admin, hash: hashPassword(newPassword), changedAt: Date.now() };
    delete this.admin.generated;
    await this.store.set('auth:admin', this.admin);
    return { ok: true };
  }

  async changeAdminUser(newUser, currentPassword) {
    if (!verifyPassword(currentPassword, this.admin.hash)) return { ok: false, reason: 'invalid credentials' };
    const user = String(newUser || '').trim().slice(0, 32);
    if (!user) return { ok: false, reason: 'invalid username' };
    this.admin.user = user;
    await this.store.set('auth:admin', this.admin);
    return { ok: true };
  }

  // --------------------------------------------------------------- sessions
  createToken(role, sub) {
    return signToken(
      { r: role, s: sub, e: Date.now() + this.config.sessionTtlMs, iat: Date.now() },
      this.secret,
    );
  }

  getSession(req) {
    const cookies = parseCookies(req.headers.cookie || '');
    const token = cookies[COOKIE_NAME];
    const payload = verifyToken(token, this.secret);
    if (!payload) return null;
    if (payload.r === 'visitor') {
      const entry = this.codes.find((c) => c.id === payload.s);
      if (!entry || !this.codeIsValid(entry)) return null;
      return { role: 'visitor', id: entry.id, label: entry.label };
    }
    if (payload.r === 'admin') {
      return { role: 'admin', id: this.admin.user, label: this.admin.user };
    }
    if (payload.r === 'guest') {
      return { role: 'guest', id: 'guest', label: 'guest' };
    }
    return null;
  }

  sessionCookie(token, req) {
    const secure =
      this.config.trustProxy && String(req.headers['x-forwarded-proto'] || '').split(',')[0].trim() === 'https';
    return `${COOKIE_NAME}=${token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${Math.floor(
      this.config.sessionTtlMs / 1000,
    )}${secure ? '; Secure' : ''}`;
  }

  clearCookie() {
    return `${COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0`;
  }
}

export default Auth;
